  "kind": "affiliate_transactions",
  "section": "4.14",
  "title": "Limitation on Transactions with Affiliates",
  "ratio_test": null,
  "baskets": [
    {
      "name": "Affiliate Transactions requiring Board Resolution",
      "fixed_amount_usd": 5000000,
      "percent": null,
      "percent_of": null,
      "greater_of": false,
      "quote": {
        "section": "4.14",
        "text": "In any Affiliate Transaction involving an amount or having a value in excess of $5 million, the Company must obtain a Board Resolution approved by a majority of the members of the Board of Directors of the Company (and a majority of the disinterested members of the Board of Directors of the Company) certifying that such Affiliate Transaction complies with this Section 4.14."
      }
    },
    {
      "name": "Affiliate Transactions requiring independent investment banking opinion",
      "fixed_amount_usd": 20000000,
      "percent": null,
      "percent_of": null,
      "greater_of": false,
      "quote": {
        "section": "4.14",
        "text": "In any Affiliate Transaction (other than a transaction or series of related transactions between the Company or any of the Restricted Subsidiaries and Interstate Highway Signs Corp. providing for the purchase of highway signage) with a value in excess of $20 million, the Company must obtain a written opinion that such Affiliate Transaction complies with this Section 4.14 from an independent investment banking firm of nationally recognized standing."
      }
    }
  ],
  "quote": {
    "section": "4.14",
    "text": "The Company will not, and will not permit any of the Restricted Subsidiaries to, directly or indirectly, enter into or suffer to exist any transaction or series of related transactions with any Affiliate (an \"Affiliate Transaction\") or extend, renew, waive or otherwise modify the terms of any Affiliate Transaction entered into prior to the Issue Date unless the terms of such Affiliate Transaction are fair and reasonable to the Company or such Restricted Subsidiary, as the case may be, or the terms of such Affiliate Transaction are at least as favorable as the terms which could be obtained by the Company or such Restricted Subsidiary, as the case may be, in a comparable transaction made on an arm's-length basis between unaffiliated parties."
  }
}
